gpW(){return"\u0625\u062c\u0645\u0627\u0644\u064a \u0627\u0644\u062a\u0634\u063a\u064a\u0644\u0627\u062a"},
gpQ(){return"\u0639\u0636\u0648 \u0645\u0646\u0630"},
gpM(){return"\u0627\u0644\u062f\u0648\u0644\u0629"},
gpJ(){return"\u0627\u0644\u0641\u0646\u0627\u0646 \u0631\u0642\u0645 1 (\u0627\u0644\u0623\u0633\u0628\u0648\u0639)"},
gpH(){return"\u0627\u0644\u0623\u0644\u0628\u0648\u0645 \u0631\u0642\u0645 1 (\u0627\u0644\u0623\u0633\u0628\u0648\u0639)"},
gpY(){return"\u0627\u0644\u0645\u0642\u0637\u0639 \u0631\u0642\u0645 1 (\u0627\u0644\u0623\u0633\u0628\u0648\u0639)"},
gq_(){return"\u0641\u0646\u0627\u0646\u0648\u0646 \u0641\u0631\u064a\u062f\u0648\u0646"},
gq0(){return"\u0645\u0642\u0627\u0637\u0639 \u0641\u0631\u064a\u062f\u0629"},
