guQ(){return"\u063a\u064a\u0631 \u0645\u062d\u062f\u062f"},
guH(){return"\u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0627\u0644\u0633\u0631\u064a \u064a\u062a\u064a\u062d \u0625\u0636\u0627\u0641\u0629 \u0623\u0648 \u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0645\u0642\u0637\u0648\u0639\u0627\u062a \u0645\u0646 \u0627\u0644\u0645\u0641\u0636\u0644\u0629 \u0645\u0628\u0627\u0634\u0631\u0629 \u0639\u0644\u0649 Last.fm."},
guE(){return"\u062a\u0641\u0639\u064a\u0644 \u0627\u0644\u0645\u0641\u0636\u0644\u0629"},
guG(){return"\u0625\u0644\u063a\u0627\u0621 \u062a\u0641\u0639\u064a\u0644 \u0627\u0644\u0645\u0641\u0636\u0644\u0629"},
gom(){return"\u0627\u0644\u0645\u0641\u0636\u0644\u0629"},
grL(){return"\u064a\u0639\u0631\u0636 \u0639\u062f\u062f \u0627\u0644\u0645\u0641\u0636\u0644\u0629 \u0641\u064a \u0627\u0644\u0625\u062d\u0635\u0627\u0626\u064a\u0627\u062a"},
grK(){return"\u0623\u0636\u0641 \u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0627\u0644\u0633\u0631\u064a \u0641\u064a \u0627\u0644\u062d\u0633\u0627\u0628 \u0644\u0644\u062a\u0641\u0639\u064a\u0644"},
gqb(){return"\u0627\u0644\u0645\u0641\u0636\u0644\u0629"},
gpA(){return"\u0639\u0631\u0636 \u0627\u0644\u0645\u0632\u064a\u062f"},
gzs(){return"\u0645\u0641\u0636\u0644\u062a\u064a"},
gzt(){return"\u0627\u0628\u062d\u062b \u0639\u0646 \u0645\u0642\u0637\u0648\u0639\u0629 \u0623\u0648 \u0641\u0646\u0627\u0646"},
gze(){return"\u0644\u0627 \u062a\u0648\u062c\u062f \u0645\u0641\u0636\u0644\u0629 \u0628\u0639\u062f."},
gqe(){return"\u0627\u0644\u0623\u062d\u062f\u062b"},
gqd(){return"\u0627\u0644\u0623\u0642\u062f\u0645"},
gqc(){return"\u0627\u0644\u0641\u0646\u0627\u0646 \u0623-\u064a"},
gqf(){return"\u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0623-\u064a"},
gzr(){return"\u064a\u062f\u0648\u064a"},
gnj(){return"\u0645\u062c\u0644\u062f \u062c\u062f\u064a\u062f"},
gzp(){return"\u0627\u0633\u0645 \u0627\u0644\u0645\u062c\u0644\u062f"},
gzj(){return"\u0627\u062e\u062a\u0631 \u0631\u0645\u0632\u064b\u0627 \u062a\u0639\u0628\u064a\u0631\u064a\u064b\u0627"},
gzi(){return"\u0631\u0645\u0632 \u062a\u0639\u0628\u064a\u0631\u064a \u0648\u0627\u062d\u062f \u0641\u0642\u0637\u060c \u0628\u0644\u0627 \u0646\u0635."},
gzl(){return"\u0627\u0644\u0648\u0635\u0641 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)"},
